use bhoo::*;
use bhoo::android_xml::LayoutState;
mod fixture {include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../apps/bhoo-web/src/android_gallery.rs"));}
const B:Rect=Rect{x:0.,y:0.,width:300.,height:160.};
fn draw(ui:&mut Ui,s:&mut LayoutState,input:Input){ui.frame(input,B,0.,|f|{fixture::LAYOUT.render(f,B,s);});}
fn touch(x:f32,pressed:bool,released:bool,time:f64)->Input{Input{pointer:Some([x,80.]),pointer_kind:PointerKind::Touch,pressed,released,time,..Input::default()}}
fn setup()->(Ui,LayoutState){let mut s=LayoutState::default();s.set_list_adapter("gallery",vec!["One".into(),"Two".into(),"Three".into()],None,None).unwrap();(Ui::default(),s)}
#[test] fn swipe_centers_next_and_cancel_returns(){let(mut ui,mut s)=setup();draw(&mut ui,&mut s,touch(150.,true,false,1.));draw(&mut ui,&mut s,touch(40.,false,false,1.1));draw(&mut ui,&mut s,touch(40.,false,true,1.4));draw(&mut ui,&mut s,Input{time:2.,..Input::default()});assert_eq!(s.displayed_children["gallery"],1);draw(&mut ui,&mut s,touch(150.,true,false,2.1));draw(&mut ui,&mut s,touch(40.,false,false,2.2));draw(&mut ui,&mut s,Input{pointer:Some([40.,80.]),cancelled:true,time:2.3,..Input::default()});draw(&mut ui,&mut s,Input{time:3.,..Input::default()});assert_eq!(s.displayed_children["gallery"],1);}
#[test] fn tapping_neighbor_selects_and_reports_it(){let(mut ui,mut s)=setup();draw(&mut ui,&mut s,Input::default());draw(&mut ui,&mut s,touch(280.,true,false,1.));draw(&mut ui,&mut s,touch(280.,false,true,1.1));assert_eq!(s.displayed_children["gallery"],1);assert_eq!(s.gallery_clicked["gallery"],1);}
#[test] fn row_width_spacing_and_duration_follow_xml(){static ROW:bhoo::android_xml::Node=bhoo::android_xml::Node{width:bhoo::android_xml::Size::Dp(80.),..row::LAYOUT};mod row {include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../apps/bhoo-web/src/android_gallery_item.rs"));}let(mut ui,mut s)=setup();s.set_list_item_template("gallery",Some(bhoo::android_xml::ListItemTemplate{row:&ROW,text_id:"gallery_title"})).unwrap();draw(&mut ui,&mut s,Input::default());let one=ui.semantics().iter().find(|v|v.label.as_ref()=="One").unwrap().bounds;let two=ui.semantics().iter().find(|v|v.label.as_ref()=="Two").unwrap().bounds;assert_eq!(one.width,80.);assert_eq!(two.x-one.x,96.);draw(&mut ui,&mut s,touch(two.x+20.,true,false,1.));draw(&mut ui,&mut s,touch(two.x+20.,false,true,1.1));draw(&mut ui,&mut s,Input{time:1.4,..Input::default()});let middle=ui.semantics().iter().find(|v|v.label.as_ref()=="Two").unwrap().bounds;assert!(middle.x>one.x);draw(&mut ui,&mut s,Input{time:2.,..Input::default()});let settled=ui.semantics().iter().find(|v|v.label.as_ref()=="Two").unwrap().bounds;assert_eq!(settled.x,one.x);}

#[test] fn fast_fling_moves_beyond_short_drag_and_stops_at_last_item(){let(mut ui,mut s)=setup();draw(&mut ui,&mut s,touch(150.,true,false,1.));draw(&mut ui,&mut s,touch(110.,false,false,1.02));draw(&mut ui,&mut s,touch(110.,false,true,1.03));draw(&mut ui,&mut s,Input{time:1.2,..Input::default()});assert!(s.displayed_children.get("gallery").copied().unwrap_or(0)>0);draw(&mut ui,&mut s,Input{time:4.,..Input::default()});assert_eq!(s.displayed_children["gallery"],2);}
#[test] fn touching_moving_gallery_does_not_jump(){let(mut ui,mut s)=setup();s.set_list_adapter("gallery",(0..10).map(|i|format!("Item {i}")).collect(),None,None).unwrap();draw(&mut ui,&mut s,touch(150.,true,false,1.));draw(&mut ui,&mut s,touch(110.,false,false,1.02));draw(&mut ui,&mut s,touch(110.,false,true,1.03));draw(&mut ui,&mut s,Input{time:1.1,..Input::default()});let selected=s.displayed_children["gallery"];let label=format!("Item {selected}");let before=ui.semantics().iter().find(|v|v.label.as_ref()==label).unwrap().bounds;draw(&mut ui,&mut s,touch(before.x+before.width/2.,true,false,1.1));let after=ui.semantics().iter().find(|v|v.label.as_ref()==label).unwrap().bounds;assert!((before.x-after.x).abs()<0.01);}
#[test] fn fast_fling_stops_at_end_without_waiting_for_full_duration(){let(mut ui,mut s)=setup();draw(&mut ui,&mut s,touch(150.,true,false,1.));draw(&mut ui,&mut s,touch(110.,false,false,1.02));draw(&mut ui,&mut s,touch(110.,false,true,1.03));draw(&mut ui,&mut s,Input{time:1.4,..Input::default()});assert_eq!(s.displayed_children["gallery"],2);let edge=ui.semantics().iter().find(|v|v.label.as_ref()=="Three").unwrap().bounds;draw(&mut ui,&mut s,Input{time:1.6,..Input::default()});let later=ui.semantics().iter().find(|v|v.label.as_ref()=="Three").unwrap().bounds;assert!((edge.x-later.x).abs()<0.01);}
#[test] fn rtl_places_next_item_left_and_rightward_swipe_advances(){let(mut ui,mut s)=setup();s.rtl=true;draw(&mut ui,&mut s,Input::default());let one=ui.semantics().iter().find(|v|v.label.as_ref()=="One").unwrap().bounds;let two=ui.semantics().iter().find(|v|v.label.as_ref()=="Two").unwrap().bounds;assert!(two.x<one.x);draw(&mut ui,&mut s,touch(150.,true,false,1.));draw(&mut ui,&mut s,touch(260.,false,false,1.1));draw(&mut ui,&mut s,touch(260.,false,true,1.4));draw(&mut ui,&mut s,Input{time:2.2,..Input::default()});assert_eq!(s.displayed_children["gallery"],1);let two=ui.semantics().iter().find(|v|v.label.as_ref()=="Two").unwrap().bounds;let three=ui.semantics().iter().find(|v|v.label.as_ref()=="Three").unwrap().bounds;assert!(three.x<two.x);}
#[test] fn rtl_fast_fling_advances_to_last(){let(mut ui,mut s)=setup();s.rtl=true;draw(&mut ui,&mut s,touch(150.,true,false,1.));draw(&mut ui,&mut s,touch(190.,false,false,1.02));draw(&mut ui,&mut s,touch(190.,false,true,1.03));draw(&mut ui,&mut s,Input{time:2.,..Input::default()});assert_eq!(s.displayed_children["gallery"],2);}
#[test] fn replacing_adapter_cancels_fling_and_preserves_stable_selected_id(){let(mut ui,mut s)=setup();s.set_list_adapter("gallery",vec!["One".into(),"Two".into(),"Three".into()],Some(vec![1,2,3]),None).unwrap();draw(&mut ui,&mut s,Input::default());s.displayed_children.insert("gallery".into(),1);draw(&mut ui,&mut s,touch(150.,true,false,1.));draw(&mut ui,&mut s,touch(110.,false,false,1.02));draw(&mut ui,&mut s,touch(110.,false,true,1.03));s.set_list_adapter("gallery",vec!["Two".into(),"One".into()],Some(vec![2,1]),None).unwrap();draw(&mut ui,&mut s,Input{time:2.,..Input::default()});assert_eq!(s.displayed_children["gallery"],0);draw(&mut ui,&mut s,Input{time:3.,..Input::default()});assert_eq!(s.displayed_children["gallery"],0);}
#[test] fn replacing_with_empty_clears_selection_then_restores_first(){let(mut ui,mut s)=setup();draw(&mut ui,&mut s,Input::default());s.displayed_children.insert("gallery".into(),2);s.set_list_adapter("gallery",vec![],None,None).unwrap();draw(&mut ui,&mut s,Input::default());assert!(!s.displayed_children.contains_key("gallery"));s.set_list_adapter("gallery",vec!["New".into()],None,None).unwrap();draw(&mut ui,&mut s,Input::default());assert!(ui.semantics().iter().any(|v|v.label.as_ref()=="New"));}
#[test] fn all_visible_narrow_items_are_rendered(){static ROW:bhoo::android_xml::Node=bhoo::android_xml::Node{width:bhoo::android_xml::Size::Dp(20.),..row::LAYOUT};mod row {include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../apps/bhoo-web/src/android_gallery_item.rs"));}static G:bhoo::android_xml::Node=bhoo::android_xml::Node{relative_rules:&[],..fixture::LAYOUT};let(mut ui,mut s)=setup();s.set_list_adapter("gallery",(0..30).map(|i|format!("Item {i}")).collect(),None,None).unwrap();s.set_list_item_template("gallery",Some(bhoo::android_xml::ListItemTemplate{row:&ROW,text_id:"gallery_title"})).unwrap();s.displayed_children.insert("gallery".into(),15);ui.frame(Input::default(),B,0.,|f|{G.render(f,B,&mut s);});assert!(ui.semantics().iter().any(|v|v.label.as_ref()=="Item 9"));assert!(ui.semantics().iter().any(|v|v.label.as_ref()=="Item 21"));}
#[test] fn reversing_preserves_initial_implicit_selection(){let(mut ui,mut s)=setup();s.set_list_adapter("gallery",vec!["One".into(),"Two".into(),"Three".into()],Some(vec![1,2,3]),None).unwrap();draw(&mut ui,&mut s,Input::default());s.set_list_adapter("gallery",vec!["Three".into(),"Two".into(),"One".into()],Some(vec![3,2,1]),None).unwrap();draw(&mut ui,&mut s,Input::default());assert_eq!(s.displayed_children["gallery"],2);}
#[test]
fn keyboard_navigation_follows_layout_direction_and_clamps() {
    for rtl in [false,true] {
        let (mut ui,mut s)=setup();s.rtl=rtl;
        draw(&mut ui,&mut s,Input::default());
        draw(&mut ui,&mut s,touch(150.,true,false,1.));
        draw(&mut ui,&mut s,touch(150.,false,true,1.1));
        let key=|key,time|Input{time,key:Some(KeyInput{key,pressed:true,repeat:false,shift:false}),..Input::default()};
        let forward=if rtl{Key::Left}else{Key::Right};let backward=if rtl{Key::Right}else{Key::Left};
        draw(&mut ui,&mut s,key(backward,2.));assert_eq!(*s.displayed_children.get("gallery").unwrap_or(&0),0);
        draw(&mut ui,&mut s,key(forward,2.1));assert_eq!(s.displayed_children["gallery"],1);
        draw(&mut ui,&mut s,key(forward,2.2));assert_eq!(s.displayed_children["gallery"],2);
        draw(&mut ui,&mut s,key(forward,2.3));assert_eq!(s.displayed_children["gallery"],2);
        draw(&mut ui,&mut s,key(Key::Enter,2.4));assert_eq!(s.gallery_clicked["gallery"],2);
    }
}
